// matematica.js
function somar(a, b) {
  return a + b;
}

function multiplicar(a, b) {
  return a * b;
}

module.exports = { somar, multiplicar };

// app.js
const { somar, multiplicar } = require('./matematica');

console.log(somar(2, 3));       // 5
console.log(multiplicar(2, 3)); // 6

// ERRADO: substitui só a referência local; module.exports fica intocado
exports = {
  somar(a, b) {
    return a + b;
  },
};

// CORRETO: atribui diretamente a module.exports
module.exports = {
  somar(a, b) {
    return a + b;
  },
};

const path = require('path');
const fs = require('fs');

console.log(__filename); // ex.: C:\projeto\src\relatorio.js
console.log(__dirname);  // ex.: C:\projeto\src

const caminhoDados = path.join(__dirname, 'dados', 'clientes.json');
const clientes = JSON.parse(fs.readFileSync(caminhoDados, 'utf8'));

// CommonJS: require pode ser condicional e dinâmico
function carregarDriver(nome) {
  // o caminho só é conhecido em tempo de execução
  return require(`./drivers/${nome}`);
}

const driver = carregarDriver(process.env.DRIVER ?? 'padrao');

// ES Modules: import é sempre estático, resolvido antes do código correr
// import driver from `./drivers/${nome}`; // isto não é válido em ESM

// package.json
{
  "name": "meu-projeto",
  "type": "module"
}

// index.js -> tratado como ES Module (por causa do "type": "module")
import { somar } from './matematica.js';
console.log(somar(2, 3));

// legado.cjs -> tratado sempre como CommonJS, apesar do "type": "module"
const { multiplicar } = require('./matematica.cjs');
console.log(multiplicar(2, 3));

