// utilizadores.js
function criarUtilizador(nome, idade) {
  return { nome, idade };
}

function listarNomes(utilizadores) {
  return utilizadores.map((u) => u.nome);
}

module.exports = { criarUtilizador, listarNomes };

// app.js
const { criarUtilizador, listarNomes } = require('./utilizadores');

const utilizadores = [
  criarUtilizador('Ana', 28),
  criarUtilizador('Bruno', 34),
  criarUtilizador('Carla', 22),
];

console.log(listarNomes(utilizadores));
// ['Ana', 'Bruno', 'Carla']

exercises.statement:
O ficheiro contador.js seguinte pretende exportar duas funções, incrementar e obterValor, que partilham uma variável valor iniciada a 0, mas tem um problema: quando outro ficheiro faz require('./contador') e tenta chamar obterValor(), obtém o erro "obterValor is not a function". Código com o problema:

let valor = 0;

exports = {
  incrementar() {
    valor++;
  },
  obterValor() {
    return valor;
  },
};

Corrija o ficheiro para que require('./contador') devolva corretamente as duas funções e o valor continue partilhado entre chamadas sucessivas de incrementar. Acrescente um comentário no código a explicar porque é que a versão original não funcionava.

exercises.solution_code:
let valor = 0;

// A atribuição direta a `exports` troca apenas a referência da variável
// local `exports` para um novo objeto; o Node continua a devolver
// `module.exports`, que ficou inalterado (o objeto vazio original).
// Por isso, para substituir por completo o que é exportado, é preciso
// atribuir diretamente a module.exports.
module.exports = {
  incrementar() {
    valor++;
  },
  obterValor() {
    return valor;
  },
};

// contadorPartilhado.js
let total = 0;

function incrementar(quantidade) {
  total += quantidade;
  return total;
}

module.exports = { incrementar };

// moduloA.js
const { incrementar } = require('./contadorPartilhado');
incrementar(1);
module.exports = {};

// moduloB.js
const { incrementar } = require('./contadorPartilhado');
incrementar(1);
module.exports = {};

// principal.js
require('./moduloA');
require('./moduloB');
const { incrementar } = require('./contadorPartilhado');

// O total impresso é 2: o Node resolve './contadorPartilhado' sempre para
// o mesmo caminho absoluto e só executa esse ficheiro uma única vez (na
// primeira vez que é pedido, dentro de moduloA.js). O module.exports
// resultante fica guardado em require.cache, por isso moduloB.js e este
// próprio ficheiro recebem, ao chamar require, a mesma instância de
// incrementar, ligada à mesma variável `total` em memória, em vez de
// recriarem um módulo novo com total a começar outra vez em 0.
console.log(incrementar(0));
// 2
